/// <summary>
/// active method
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();

    element.design().controlName(formControlStr(PurchAgreement, AVACallOffReleaseItem)).enabled(element.avaEnableCallOff());

    return ret;
}

/// <summary>
/// Deletes the current Agreement Line record and sets the state of the line buttons.
/// </summary>
public void delete()
{
    next delete();

    this.executeQuery();
}
